package com.tihai.utils;
import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.*;import com.tihai.dubbo.pojo.course.Course;import org.jsoup.*;import org.jsoup.nodes.*;import okhttp3.*;import java.util.*;import java.io.*;
@Service public class SigninCatalog {
 @Autowired private com.tihai.utils.AccountRegistry registry;@Autowired private JdbcTemplate db;@Autowired private CourseExamCatalog auth;private final ObjectMapper json=new ObjectMapper();private final Map<String,Entry> entries=new java.util.concurrent.ConcurrentHashMap<>();private Map<String,Object> cache;private long updated;private String scopeKey="";
 public static class Entry {public String id,account,courseKey,courseId,clazzId,activeId,title,course,kind,url;public boolean ongoing;}
 public CourseExamCatalog auth(){return auth;}
 public Entry entry(String id)throws IOException{Entry e=entries.get(id);if(e==null)throw new IOException("签到入口已过期，请刷新");return e;}
 public static String key(String account,String course,String active){return UUID.nameUUIDFromBytes((account+"|signin|"+course+"|"+active).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString();}
 public synchronized void invalidate(){updated=0;}
 public static List<Entry> parse(String body,String account,Course course,String fid)throws IOException{JsonNode root=new ObjectMapper().readTree(body);if(!(root.path("result").asInt()==1||root.path("result").asBoolean(false)))throw new IOException("课堂活动接口未成功返回");JsonNode list=root.path("data").path("activeList");if(!list.isArray())throw new IOException("课堂活动列表结构未识别");List<Entry> out=new ArrayList<>();for(JsonNode a:list){if(a.path("activeType").asInt(-1)!=2)continue;String active=a.path("id").asText();if(!active.matches("[0-9]+"))throw new IOException("活动标识无效");Entry e=new Entry();e.account=account;e.courseId=course.getCourseId();e.clazzId=course.getClazzId();e.activeId=active;e.course=course.getTitle();e.courseKey=key(account,e.courseId,"course");e.id=key(account,e.courseId,active);e.title=a.path("nameOne").asText("签到");String other=a.path("otherId").asText();e.kind="0".equals(other)?"normal":"4".equals(other)?"location":"manual";e.ongoing=a.path("status").asInt()==1;e.url=HttpUrl.parse("https://mobilelearn.chaoxing.com/widget/sign/pcStuSignController/preSign").newBuilder().addQueryParameter("activeId",active).addQueryParameter("classId",e.clazzId).addQueryParameter("fid",fid).addQueryParameter("courseId",e.courseId).build().toString();out.add(e);}return out;}
 public synchronized Map<String,Object> list(){if(!scopeKey.equals(AccountScope.cacheKey())){cache=null;scopeKey=AccountScope.cacheKey();}if(cache!=null&&System.currentTimeMillis()-updated<30000)return copy(cache);List<Map<String,Object>> items=new ArrayList<>(),courses=new ArrayList<>();List<String> errors=new ArrayList<>();for(Map<String,Object> accountRow:com.tihai.utils.AccountScope.accounts(db)){String account=String.valueOf(accountRow.get("login_account"));try{Set<String> chosen=new HashSet<>(db.queryForList("SELECT DISTINCT course_id FROM th_wk_queue WHERE login_account=?",String.class,account));CourseUtil util=auth.session(account);OkHttpClient http=util.initSession(false,false).newBuilder().callTimeout(25,java.util.concurrent.TimeUnit.SECONDS).build();for(Course c:util.getCourseList())if(chosen.contains(c.getCourseId())){Map<String,Object> course=new LinkedHashMap<>();course.put("id",key(account,c.getCourseId(),"course"));course.put("title",c.getTitle());courses.add(course);try{HttpUrl url=HttpUrl.parse("https://mobilelearn.chaoxing.com/v2/apis/active/student/activelist").newBuilder().addQueryParameter("fid","0").addQueryParameter("courseId",c.getCourseId()).addQueryParameter("classId",c.getClazzId()).addQueryParameter("showNotStartedActive","0").build();String body=CourseExamCatalog.get(http,url.toString());List<Entry> rows=parse(body,account,c,"0");String fid="0";if(!rows.isEmpty()){String page=CourseExamCatalog.get(http,HttpUrl.parse("https://mobilelearn.chaoxing.com/widget/pcpick/stu/index").newBuilder().addQueryParameter("courseId",c.getCourseId()).addQueryParameter("jclassId",c.getClazzId()).build().toString());Element field=Jsoup.parse(page).getElementById("fid");if(field==null||!field.val().matches("[0-9]+"))throw new IOException("未读取到平台组织标识");fid=field.val();rows=parse(body,account,c,fid);}for(Entry e:rows){entries.put(e.id,e);if(registry!=null)registry.resource("signin",e.id,e.account);Map<String,Object> item=new LinkedHashMap<>();item.put("id",e.id);item.put("courseKey",e.courseKey);item.put("title",e.title);item.put("course",e.course);item.put("kind",e.kind);item.put("ongoing",e.ongoing);item.put("platformStatus",e.ongoing?"进行中":"已结束");item.put("detail","location".equals(e.kind)?"平台要求手机App提供位置信息":"normal".equals(e.kind)?"普通签到 · 提交前核对页面要求":"当前签到方式需人工处理");items.add(item);}}catch(Exception ex){errors.add("部分课程签到活动读取失败，请刷新或重新登录");}}}catch(Exception ex){errors.add("签到账号会话不可用，请重新查询课程登录");}}
  Map<String,Object> result=new LinkedHashMap<>();result.put("items",items);result.put("courses",courses);result.put("errors",errors);result.put("message","已添加课程的签到活动 · 每30秒更新 · 仅普通签到可自动处理");cache=result;updated=System.currentTimeMillis();return copy(result);}
 private Map<String,Object> copy(Map<String,Object> value){return json.convertValue(value,Map.class);}
 public static String inspect(String html,Entry e)throws IOException{Document d=Jsoup.parse(html);String text=d.body().text();if(text.contains("签到成功")||text.contains("已签到"))return "completed";if(text.contains("手机App")||text.contains("手机APP")||text.contains("手机提供位置信息"))return "phone_required";if(!"normal".equals(e.kind))return "manual";for(String[] pair:new String[][]{{"activeId",e.activeId},{"courseId",e.courseId},{"classId",e.clazzId}}){Element field=d.getElementById(pair[0]);if(field==null||!pair[1].equals(field.val()))throw new IOException("签到活动身份变化");}Element active=d.getElementById("activeStatus");if(active==null||!"1".equals(active.val()))return "ended";if(html.contains("function checkIfValidate")&&html.contains("/widget/sign/pcStuSignController/signIn"))return "ready";return "manual";}
}
